13	)
14	
15	func baseVoteInput(id string) *CreateVoteInput {
16		return &CreateVoteInput{
17			ID: id,
18			Members: []VoteMember{
19				{ID: "alice", Weight: 300},
20				{ID: "bob", Weight: 200},
21				{ID: "carol", Weight: 100},
22				{ID: "dave", Weight: 400},
23			},
24			Delegations: []Delegation{{From: "bob", To: "alice"}, {From: "carol", To: "alice"}},
25			Quorum:      600,
26			StartAt:     100,
27			Deadline:    200,
28			TimelockEnd: 300,
29			Actions:     []string{"transfer:audits:100"},
30		}
31	}
32	
33	func mustCreateVote(t *testing.T, store *Store, in *CreateVoteInput) *VoteProposalView {
34		t.Helper()
35		view, existed, err := store.CreateVoteProposal(in)
36		if err != nil || existed {
