865				extra := map[string]any{"representative": "alice", "weight": 600, "support": true, "voted_at": 151}
866				p["ballots"] = append(p["ballots"].([]any), extra)
867			}),
868			"tally before deadline": mutate(func(p map[string]any) {
869				p["tally"].(map[string]any)["tallied_at"] = 199
870			}),
871			"tally disagrees with ballots": mutate(func(p map[string]any) {
872				p["tally"].(map[string]any)["for_weight"] = 601
873			}),
874			"unknown vote state": mutate(func(p map[string]any) {
875				p["state"] = "approved"
876			}),
877			"quorum out of range": mutate(func(p map[string]any) {
878				p["quorum"] = 1001
879			}),
880		}
881		// id collision：在 register 来源表里注入同一编号。
882		collision := mutate(func(p map[string]any) {})
883		var cd map[string]any
884		if err := json.Unmarshal(collision, &cd); err != nil {
885			t.Fatal(err)
886		}
887		cd["proposals"] = map[string]any{"gip-tamper": map[string]any{
888			"id": "gip-tamper", "state": "passed", "timelock_end": 300,
889			"actions": []any{"transfer:audits:100"},
890		}}
891		if raw, err := json.MarshalIndent(cd, "", "  "); err != nil {
892			t.Fatal(err)
893		} else {
894			cases["id collision"] = append(raw, '\n')
895		}
896		for name, raw := range cases {
897			t.Run(name, func(t *testing.T) {
898				bad := filepath.Join(dir, "bad-"+strings.ReplaceAll(name, " ", "-")+".json")
