1585	  "version": 1,
1586	  "initial_treasury": 1000,
1587	  "treasury": 1000,
1588	  "balances": {},
1589	  "proposals": {},
1590	  "receipts": [],
1591	  "vote_proposals": {
1592	    "gip-fz": {
1593	      "id": "gip-fz",
1594	      "state": "voting",
1595	      "members": [{"id": "a", "weight": 5}, {"id": "b", "weight": 5}],
1596	      "delegations": [],
1597	      "quorum": 1,
1598	      "start_at": 0,
1599	      "deadline": 10,
1600	      "timelock_end": 10,
1601	      "actions": [],
1602	      "ballots": [{"representative": "b", "weight": 5, "support": false, "voted_at": 0}]
1603	    }
1604	  }
1605	}
1606	`
1607		if err := os.WriteFile(handwritten, []byte(raw), 0o600); err != nil {
1608			t.Fatal(err)
1609		}
